-- Source: FED_OSHA_ITA_CASE_DETAIL_2025 (330447 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: DATE_OF_INCIDENT was a bare try_to_date() (no format -- a
-- pure-digit value would misread as epoch seconds) and DAFW_NUM_AWAY/
-- DJTR_NUM_TR were bare try_to_number() calls (silently rounds decimals).
-- Live-checked: 0 pure-digit rows in DATE_OF_INCIDENT and 0 fractional values
-- in either count column across all 330,447 rows -- clean today, but
-- unguarded. DATE_OF_DEATH and CREATED_TIMESTAMP below are left alone: both
-- already carry explicit alpha-month formats plus trim/nullif (no epoch
-- risk). A matching staging model exists
-- (models/staging/fed_osha_ita_case_detail_2025) and casts these exact three
-- columns the same way, but it leaves date_of_death/created_timestamp as raw
-- TEXT -- swapping to ref() would have demoted those two from their current
-- DATE/TIMESTAMP type, so wrapped the three bare casts in place instead.

with source as (
    select * from {{ source('ripple_raw', 'FED_OSHA_ITA_CASE_DETAIL_2025') }}
)

select
    ID as id,
    ESTABLISHMENT_ID as establishment_id,
    ESTABLISHMENT_NAME as establishment_name,
    EIN as ein,
    COMPANY_NAME as company_name,
    STREET_ADDRESS as street_address,
    CITY as city,
    STATE as state,
    ZIP_CODE as zip_code,
    NAICS_CODE as naics_code,
    {{ ripple_num('NAICS_YEAR') }} as naics_year,
    INDUSTRY_DESCRIPTION as industry_description,
    ESTABLISHMENT_TYPE as establishment_type,
    SIZE as size,
    {{ ripple_num('ANNUAL_AVERAGE_EMPLOYEES') }} as annual_average_employees,
    {{ ripple_num('TOTAL_HOURS_WORKED') }} as total_hours_worked,
    CASE_NUMBER as case_number,
    JOB_DESCRIPTION as job_description,
    SOC_CODE as soc_code,
    SOC_DESCRIPTION as soc_description,
    SOC_PROBABILITY as soc_probability,
    UNEXPECTED_NAICS_SOC_COMBO as unexpected_naics_soc_combo,
    {{ stg_date('DATE_OF_INCIDENT') }} as date_of_incident,
    INCIDENT_OUTCOME as incident_outcome,
    {{ stg_int('DAFW_NUM_AWAY') }} as dafw_num_away,
    {{ stg_int('DJTR_NUM_TR') }} as djtr_num_tr,
    TYPE_OF_INCIDENT as type_of_incident,
    TIME_STARTED_WORK as time_started_work,
    TIME_OF_INCIDENT as time_of_incident,
    TIME_UNKNOWN as time_unknown,
    try_to_date(nullif(trim(DATE_OF_DEATH), ''), 'DDMONYY:HH24:MI:SS') as date_of_death,
    coalesce(try_to_timestamp(nullif(trim(CREATED_TIMESTAMP), ''), 'DDMONYYYY:HH24:MI:SS'), try_to_timestamp(nullif(trim(CREATED_TIMESTAMP), ''), 'DDMONYY:HH24:MI:SS')) as created_timestamp,
    YEAR_OF_FILING as year_of_filing,
    NEW_INCIDENT_LOCATION as new_incident_location,
    NEW_INCIDENT_DESCRIPTION as new_incident_description,
    NEW_NAR_BEFORE_INCIDENT as new_nar_before_incident,
    NEW_NAR_WHAT_HAPPENED as new_nar_what_happened,
    NEW_NAR_INJURY_ILLNESS as new_nar_injury_illness,
    NEW_NAR_OBJECT_SUBSTANCE as new_nar_object_substance
from source
